(function(){'use strict';const F=THFinanceCore,ranges={};
const range=(key,basis)=>ranges[key]||(ranges[key]={start:'',end:'',basis});
function controls(key,choices){const r=range(key,choices[0][0]);return `<div class="op-range"><label>Dasar tanggal<select data-op-key="${key}" data-op-field="basis">${choices.map(([v,t])=>`<option value="${v}" ${r.basis===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Dari<input type="date" data-op-key="${key}" data-op-field="start" value="${r.start}"></label><label>Sampai<input type="date" data-op-key="${key}" data-op-field="end" value="${r.end}"></label><button class="btn small" data-op-reset="${key}">Semua tanggal</button></div>`;}
function matches(x,key){const r=ranges[key];if(!r||!r.start&&!r.end)return true;const values=r.basis==='paymentDates'?(x.financePayments?.length?x.financePayments.map(p=>p.date):x.history?.some(p=>p.amount)?x.history.filter(p=>p.amount).map(p=>p.date||p.at):[x.paidAt]):[x[r.basis]];return values.some(v=>{const d=F.dateOf(v);return d&&(!r.start||d>=r.start)&&(!r.end||d<=r.end)})}
function wrap(name,key,choices,props){const old=window[name];/* top-level declarations are global */window[name]=function(...args){const original=db;try{const changed={...db};for(const p of props)changed[p]=db[p].filter(x=>matches(x,key));db=changed;return controls(key,choices)+old(...args);}finally{db=original;}};}
wrap('renderLaundry','laundry',[['created','Order dibuat'],['completed','Order selesai'],['handoverAt','Diserahkan'],['paymentDates','Pembayaran diterima']],[ 'orders']);
wrap('renderTenants','tenants',[['start','Mulai tinggal'],['end','Akhir tinggal'],['checkout','Checkout'],['createdAt','Pelanggan dicatat']],['tenants']);
wrap('renderInvoices','invoices',[['issuedDate','Invoice dibuat'],['serviceDate','Jasa diakui'],['due','Jatuh tempo'],['paymentDates','Pembayaran diterima']],['invoices']);
wrap('renderClosing','closing',[['date','Tanggal closing'],['depositAt','Tanggal disetor']],['settlements']);
const oldTeam=renderTeam;renderTeam=function(){if(!['reports','evaluations','audit'].includes(ui.tab))return oldTeam();const key=ui.tab,p=key==='reports'?'reports':key==='evaluations'?'evaluations':'audit',basis=key==='audit'?'at':'date',original=db;try{db={...db,[p]:db[p].filter(x=>matches(x,key))};return controls(key,[[basis,key==='audit'?'Waktu aktivitas':'Tanggal laporan']])+oldTeam();}finally{db=original;}};
for(const [action,key,props] of [['export-orders','laundry',['orders']],['export-invoices','invoices',['invoices']],['export-reports','reports',['reports']],['export-audit','audit',['audit']]]){const old=actions[action];actions[action]=async function(...args){const original=db;try{db={...db};for(const p of props)db[p]=original[p].filter(x=>matches(x,key)).filter(x=>key!=='laundry'||(ui.filter==='Semua'||ui.filter==='Prioritas'&&alertFor(x,ui.date).level!=='green'||ui.filter==='Belum lunas'&&!paid(x)||x.stage===ui.filter)&&`${x.id} ${x.customer} ${x.room} ${x.building||''} ${x.floor||''} ${x.roomType||''}`.toLowerCase().includes(ui.search.toLowerCase())).filter(x=>key!=='reports'||!ui.search||`${getEmp(x.employeeId)} ${x.activity} ${x.division} ${x.date}`.toLowerCase().includes(ui.search.toLowerCase()));return await old(...args);}finally{db=original;}};}
document.addEventListener('change',e=>{const t=e.target,k=t.dataset.opKey;if(!k)return;const r=ranges[k],next={...r,[t.dataset.opField]:t.value};if(next.start&&next.end&&next.start>next.end){toast('Tanggal awal harus sebelum tanggal akhir.');t.value=r[t.dataset.opField];return;}ranges[k]=next;render();});document.addEventListener('click',e=>{const b=e.target.closest('[data-op-reset]');if(!b)return;ranges[b.dataset.opReset].start='';ranges[b.dataset.opReset].end='';render();});
window.THDateFilters={matches,ranges};
})();
